import{_ as o,o as r,c as t,ag as a}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"ADR-0002: memU — 借鉴设计而非引入依赖","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-memu-design-not-dependency.md","filePath":"adr/0002-memu-design-not-dependency.md"}'),n={name:"adr/0002-memu-design-not-dependency.md"};function i(m,e,l,c,d,s){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0002-memu-—-借鉴设计而非引入依赖" tabindex="-1">ADR-0002: memU — 借鉴设计而非引入依赖 <a class="header-anchor" href="#adr-0002-memu-—-借鉴设计而非引入依赖" aria-label="Permalink to &quot;ADR-0002: memU — 借鉴设计而非引入依赖&quot;">​</a></h1><ul><li><strong>状态</strong>：Accepted（2026-07-10 按 PR #477 评审意见修订后采纳）；下方 fallback 已由 <a href="./0003-memu-cli-integration.html">ADR-0003</a> 于 2026-07-16 激活</li><li><strong>日期</strong>：2026-07-08，修订 2026-07-10</li><li><strong>关联</strong>：<a href="./0001-llm-mode-memory.html">ADR-0001</a>、<a href="./0003-memu-cli-integration.html">ADR-0003</a>、<a href="https://github.com/XnneHangLab/XnneHangLab/issues/471" target="_blank" rel="noreferrer">#471</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>计划把 <a href="https://github.com/NevaMind-AI/memU" target="_blank" rel="noreferrer">memU</a>（NevaMind-AI，Apache-2.0，~14k stars，AI companion 记忆框架）引入为记忆插件。2026-07 调研结论：</p><ol><li><strong>Python 版本硬阻塞</strong>：<code>memu-py</code> 1.5.1 要求 <code>requires-python &gt;= 3.13</code>，本项目为 Python 3.11。唯一兼容 3.11 的版本是 2025-08 的 0.1.x（API 已废弃）。5 个月内 Python floor 改了 4 次。</li><li><strong>没有 wiki-link 机制</strong>：memU 的跨分类关联靠 entry↔category 关系边 + 多分类归属 + embeddings，内容内链接（<code>[[...]]</code>）不存在——而这正是 ADR-0001 的核心差异化设计。引入 memU 意味着放弃差异化而不是实现它。</li><li><strong>架构已转向 DB-first</strong>：v1.x 的事实存储是 SQLModel（SQLite / Postgres+pgvector），markdown 目录只是默认关闭的导出投影。&quot;markdown 文件式记忆&quot;是 memU v0.1 的旧印象。</li><li><strong>Beta 级 API 剧变</strong>：<code>MemoryItem/MemoryCategory</code> → <code>RecallEntry/RecallFile</code> 重命名，0.2 → 1.0 只用了 3 个月；<code>memorize</code> 只接受文件式 <code>resource_url</code>（对话需先落盘）；<code>dedupe_merge</code> 是文档标明的占位 no-op。</li><li><strong>依赖与部署负担</strong>：依赖树含 langchain-core / sqlmodel / alembic / anthropic / numpy≥2.3；<code>memU-server</code>（独立仓库）是 AGPL-3.0 + Postgres + pgvector + Temporal，桌面应用不可捆绑。</li></ol><blockquote><p><strong>2026-07-10 更新</strong>（PR #477 评审）：复核了 memU 最新 ADR（<a href="https://github.com/NevaMind-AI/memU/blob/main/docs/adr/0006-from-memory-item-category-to-tracked-workspace-memorization.md" target="_blank" rel="noreferrer">0006</a> / <a href="https://github.com/NevaMind-AI/memU/blob/main/docs/adr/0007-three-independent-memory-lines-wiki-graph.md" target="_blank" rel="noreferrer">0007</a> / <a href="https://github.com/NevaMind-AI/memU/blob/main/docs/adr/0008-two-integration-surfaces-hooks-and-api.md" target="_blank" rel="noreferrer">0008</a>）。memU 正在放弃旧的 memorize/retrieve：检索收敛为<strong>单趟混合搜索</strong>（BM25 + embedding 融合，0 次 LLM 调用，明确无图、无多跳、无 sufficiency 管线），写入收敛为 trajectory 单次抽取 + 异步后台（hook 契约 on_turn / on_prompt）。下方借鉴清单已同步到该终态。</p></blockquote><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p><strong>不引入 <code>memu-py</code> 依赖。</strong> 在记忆管线（ADR-0001）的自研实现中借鉴 memU 已被验证的设计：</p><ol><li><strong>L0 → L1 → L2 数据分层</strong>（memU ADR-0007）：resource（原始来源）→ category 文档（每分类一个 markdown 文件）→ item 切片（检索基本单元）。resource / item / category 三层保留。</li><li><strong>提取 prompt 设计原则</strong>：条目自包含（self-contained）、与语料同语言（中文语料产中文记忆）、叙述者/主体区分、排除短时效信息（no-ephemera）；memory_type 六类（profile / event / knowledge / behavior / skill / tool）作 categories 顶层参考</li><li><strong>单趟混合检索，检索不调 LLM</strong>（memU ADR-0007 终态）：BM25 关键词为底、embedding 余弦为可选融合（min-max 归一）。memU 已放弃旧的 route_intention / sufficiency 多级 LLM 管线与图遍历——直接采用其终态，不重走弯路</li><li><strong>集成时序 = hook 契约</strong>（memU ADR-0008）：写入异步后台（<code>on_turn</code> ≈ 本项目 <code>HookPlugin.on_after_turn</code>）、注入同步临界路径 + token 预算 + fail-open（<code>on_prompt</code> ≈ <code>on_before_turn</code>）</li></ol><h3 id="fallback-备选-已于-2026-07-16-由-adr-0003-激活" tabindex="-1">Fallback（备选，已于 2026-07-16 由 <a href="./0003-memu-cli-integration.html">ADR-0003</a> 激活） <a class="header-anchor" href="#fallback-备选-已于-2026-07-16-由-adr-0003-激活" aria-label="Permalink to &quot;Fallback（备选，已于 2026-07-16 由 [ADR-0003](./0003-memu-cli-integration) 激活）&quot;">​</a></h3><p>uv sidecar 方案——<code>uv run --python 3.13</code> 拉起独立进程，SQLite 后端，embedding 指向用户自己的 LLM 供应商或本地 Ollama。代价：桌面应用多一个进程生命周期要管理，且承担 Beta API 升级风险。</p><blockquote><p><strong>2026-07-16 更新</strong>：该 fallback 已落地为<strong>实验性 opt-in</strong> 的第二记忆后端（与 wikimem 并列，用于对照评测），但形态随上游 pivot 调整：上游收敛为 <code>memu-cli</code>（<code>memu-py</code> 冻结待归档）、CLI 即唯一契约面、按短生命周期进程设计——因此不是常驻 localhost shim，而是<strong>每次调用拉起 <code>memu</code> CLI 短生命周期子进程</strong>；memU 由 <code>packages/memU</code> 镜像<strong>子模块源码构建</strong>（不拉 PyPI wheel），贯彻「子模块 + 不 pip install」的供应链方针。详见 <a href="./0003-memu-cli-integration.html">ADR-0003</a>。</p></blockquote><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li>ADR-0001 的设计与 memU 核心理念重合度约 80%（categories、原子条目、多分类归属、LLM/RAG 双检索、user-scoped metadata）——重合部分借鉴设计即可获得；剩下 20%（wiki-links、扁平可审查存储）恰是 memU 没有的</li><li>三条集成路径全部有结构性成本：in-process 被 Python 3.13 阻塞；sidecar 增加进程管理 + API churn 风险；memU-server 直接不可行（AGPL + 重基建）</li><li>全项目升级 Python 3.13 是先决条件级别的大动作（Live2D / ONNX / TTS 依赖链需全部验证），不应由一个记忆插件驱动</li></ul><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><p><strong>正面</strong></p><ul><li>无 Python 版本冲突、无 Beta API 升级风险、依赖树不膨胀</li><li>wiki-links 差异化设计得以保留</li><li>提取 prompt / 检索管线按中文语料与桌面场景定制</li></ul><p><strong>负面 / 代价</strong></p><ul><li>提取与检索管线需自行实现和调优（memU 的 prompt 可作起点：<code>src/memu/prompts/memory_type/*.py</code>，Apache-2.0）</li><li>无法直接受益于 memU 上游迭代</li></ul><p><strong>复审条件</strong>（满足任一时重新评估本决策）</p><ul><li><code>memu-py</code> 恢复支持 Python 3.11/3.12，或本项目完成 3.13 升级</li><li>memU 引入 in-content links 机制</li><li>自研记忆管线实现两个里程碑后效果不达预期（届时启用 sidecar fallback）</li></ul>',21)])])}const h=o(n,[["render",i]]);export{p as __pageData,h as default};
